/**
 * IIIF Image API request for a pixel region: `{region}/{size}/0/default.jpg`.
 * `outputWidth` is a `sizeByW` value and is clamped to MAX_OUTPUT_WIDTH.
 */
export function imageRequestUrl(service, region, outputWidth, { quality = 'default', format = 'jpg' } = {}) {
  if (!service) return null;
  const r = regionRequest(region);
  if (!r) return null;
  const width = Math.max(16, Math.min(Math.round(outputWidth || MAX_OUTPUT_WIDTH), MAX_OUTPUT_WIDTH));
  return `${String(service).replace(/\/+$/, '')}/${r}/${width},/0/${quality}.${format}`;
}

/**
 * A region is either one rect in image pixels or `{ view, bounds }`; when a view
 * is given we ask for exactly that rectangle. A full-sheet view uses `full`
 * instead of `0,0,w,h` because some services only implement `full`.
 */
export function regionRequest(region) {
  const rect = region?.view ?? region;
  if (!rect) return null;
  const { x, y, w, h } = rect;
  if (![x, y, w, h].every((v) => Number.isFinite(v)) || w <= 0 || h <= 0) return null;
  if (x <= 0 && y <= 0 && region?.bounds && w >= region.bounds.w - 1 && h >= region.bounds.h - 1) return 'full';
  return `${Math.round(x)},${Math.round(y)},${Math.round(w)},${Math.round(h)}`;
}

/** Full-sheet derivative at a given width (used for previews/fallbacks). */
export function fullImageUrl(service, width = 1000) {
  if (!service) return null;
  return imageRequestUrl(service, { x: 0, y: 0, w: 1, h: 1, full: true }, width)?.replace(/\/0,0,1,1\//, '/full/') ?? null;
}

