/** Bounds of a sheet, the space every view is clamped to. */
export function boundsForCanvas(width, height) {
  return { x: 0, y: 0, w: width, h: height };
}

/**
 * Fit a view to a stage aspect ratio without leaving the sheet: the returned
 * view always covers `bounds` as far as possible, so a portrait sheet in a wide
 * stage is letterboxed instead of requesting pixels outside the image.
 */
export function fitView(bounds, stageAspect) {
  const aspect = Number.isFinite(stageAspect) && stageAspect > 0 ? stageAspect : bounds.w / bounds.h;
  let w = bounds.w;
  let h = bounds.h;
  if (w / h < aspect) {
    // stage is wider than the sheet: keep the width, we cannot add margins.
    w = bounds.w;
    h = w / aspect;
  } else {
    h = bounds.h;
    w = h * aspect;
  }
  return clampView({ x: bounds.x + (bounds.w - w) / 2, y: bounds.y + (bounds.h - h) / 2, w, h }, bounds);
}

